UPDATE inventories
SET available_quantity = #{availableQuantity}, version = version + 1
WHERE book_id = #{bookId}

UPDATE inventories
SET reserved_quantity = reserved_quantity - #{quantity}, sold_quantity = sold_quantity + #{quantity}, version = version + 1
WHERE book_id = #{bookId} AND reserved_quantity >= #{quantity}

UPDATE inventories
SET reserved_quantity = reserved_quantity - #{quantity}, available_quantity = available_quantity + #{quantity}, version = version + 1
WHERE book_id = #{bookId} AND reserved_quantity >= #{quantity}
